          "description": "Gravatar ID, see [documentation](https://en.gravatar.com/site/implement/).",
          "pattern": "^[a-f0-9]{32}$",
          "readOnly": true,
          "type": "string"
        },
        "is_active": {
          "description": "Whether the user is able to login. Set to `false` to ban a user.",
          "type": "boolean"
